import React, { useState, useEffect } from "react";

function PostList() {
  const [posts, setPosts] = useState([]);
  const [userId, setUserId] = useState(null);

  useEffect(() => {
    // 获取当前用户 ID
    fetch("http://localhost:8000/api/current-user", {
      credentials: "include",
    })
      .then((res) => res.json())
      .then((user) => {
        setUserId(user.id);
        return fetch(`http://localhost:8000/items?userId=${user.id}`, {
          credentials: "include",
        });
      })
      .then((res) => res.json())
      .then((data) => setPosts(data))
      .catch((err) => console.error("Failed to load user posts:", err));
  }, []);

  const handleDelete = async (postId) => {
    if (!window.confirm("Are you sure you want to delete this post?")) return;

    try {
      const res = await fetch(`http://localhost:8000/items/${postId}`, {
        method: "DELETE",
        credentials: "include",
      });

      if (!res.ok) throw new Error("Delete failed");

      setPosts((prev) => prev.filter((post) => post.id !== postId));
    } catch (err) {
      alert("Failed to delete post.");
      console.error(err);
    }
  };

  return (
    <div className="mt-10 space-y-6">
      <h2 className="text-xl font-bold">My Posts</h2>
      {posts.map((post) => (
        <div key={post.id} className="p-4 border rounded shadow">
          {post.imageUrl && (
            <img
              src={post.imageUrl}
              alt="Post"
              className="w-full h-48 object-cover mb-2"
            />
          )}
          <h3 className="text-lg font-semibold">{post.name}</h3>
          <p>{post.description}</p>
          <p className="text-sm text-gray-500">
            📍 {post.featuredPlace || "No location"}
          </p>
          <p className="text-sm text-yellow-600">
            ⭐ Rating: {post.rating ? post.rating.toFixed(1) : "N/A"}
          </p>
          <p className="text-xs text-gray-400">
            🕒 {new Date(post.createdAt).toLocaleString()}
          </p>
          <button
            className="mt-2 px-3 py-1 bg-red-500 text-white rounded text-sm"
            onClick={() => handleDelete(post.id)}
          >
            Delete
          </button>
        </div>
      ))}
    </div>
  );
}
